In addition to the default formatting in the standard library as mentioned by AndyKelley, adding a function called &quot;format&quot; to your type will override the standard behavior and allow arbitrary custom formatting. see this example from the test case in std.fmt:<p><pre><code>  const Vec2 = struct {       const SelfType = @This();       x: f32,       y: f32,          pub fn format(   	  self: SelfType,   	  comptime fmt: []const u8,   	  context: var,   	  comptime Errors: type,   	  output: fn (@typeOf(context), []const u8) Errors!void,       ) Errors!void {   	  switch (fmt.len) {   	  	  0 =&gt; return std.fmt.format(context, Errors, output, &quot;({.3},{.3})&quot;, self.x, self.y),   	  	  1 =&gt; switch (fmt[0]) {   	  	  	  &#x2F;&#x2F;point format   	  	  	  &#x27;p&#x27; =&gt; return std.fmt.format(context, Errors, output, &quot;({.3},{.3})&quot;, self.x, self.y),   	  	  	  &#x2F;&#x2F;dimension format   	  	  	  &#x27;d&#x27; =&gt; return std.fmt.format(context, Errors, output, &quot;{.3}x{.3}&quot;, self.x, self.y),   	  	  	  else =&gt; unreachable,   	  	  },   	  	  else =&gt; unreachable,   	  }       }   };    var value = Vec2 {       .x = 10.2,       .y = 2.22,   };    try testFmt(&quot;point: (10.200,2.220)
&quot;, &quot;point: {}
&quot;, &amp;value);   try testFmt(&quot;dim: 10.200x2.220
&quot;, &quot;dim: {d}
&quot;, &amp;value);</code></pre>
